const operationalTables = new Set([
  "store_cart", "store_cart_item", "api_rate_limits", "notification_outbox",
  "customer_notification_read", "store_customer_favorite", "store_customer",
  "store_customer_address", "store_customer_token",
  "admin_notification_seen", "contact_messages", "contact_incoming_replies",
  "newsletter_subscribers", "chatbot_conversations", "chatbot_messages",
])

// These statements are generated by the application, never supplied as SQL by
// a visitor. Extra CTE/function names only add harmless dependency tags.
export function readTables(sql: string): string[] {
  return [...new Set([...sql.matchAll(/\b(?:FROM|JOIN)\s+(?:ONLY\s+)?(?:"?public"?\.)?"?([a-z_][a-z0-9_]*)"?/gi)]
    .map(match => match[1].toLowerCase()))]
}

export function mutationTables(sql: string): string[] {
  return [...new Set([...sql.matchAll(/\b(?:INSERT\s+INTO|UPDATE(?!\s+(?:SET|OF|SKIP|NOWAIT)\b)|DELETE\s+FROM|(?:ALTER|DROP|CREATE)\s+TABLE(?:\s+IF\s+(?:NOT\s+)?EXISTS)?|TRUNCATE(?:\s+TABLE)?)\s+(?:ONLY\s+)?(?:"?public"?\.)?"?([a-z_][a-z0-9_]*)"?/gi)]
    .map(match => match[1].toLowerCase()))]
}

export function shouldInvalidateCatalog(sql: string, rowCount: number | null): boolean {
  if (rowCount === 0) return false
  // ON CONFLICT DO UPDATE SET is an upsert clause, not an UPDATE of a table
  // named "set". Treating it as one invalidated every cache on rate-limit hits.
  const tables = mutationTables(sql)
  if (/\b(?:ALTER|DROP|CREATE)\s+TABLE\b|\bTRUNCATE\b/i.test(sql)) return true
  return tables.some(table => !operationalTables.has(table))
}
